def is_valid_parentheses(s):
    stack=[]
    pairs={')':'(',']':'[','}':'{'}
    for c in s:
        if c in '([{':
            stack.append(c)
        elif c in ')]}':
            if not stack or stack[-1]!=pairs[c]:
                return False
            stack.pop()
        else:
            return False
    return not stack

