def count_subarrays_and_k(nums,k):
    res=0
    prev={}
    for num in nums:
        cur={num:1}
        for v,c in prev.items():
            nv=v&num
            cur[nv]=cur.get(nv,0)+c
        prev=cur
        res+=prev.get(k,0)
    return res
